SELECT fi.id AS invoiceId, fi.invoice_no AS invoiceNo, fi.invoice_kind AS invoiceType, fi.supplier_id AS supplierId, fi.seller_name AS sellerName, fi.seller_tax_no AS sellerTaxNo, fi.invoice_date AS invoiceDate, fi.amount_with_tax AS amountWithTax, fi.amount_without_tax AS amountWithoutTax, fi.tax_amount AS taxAmount, fi.currency AS currency, fi.status AS status, fi.posting_status AS postingStatus, fi.reconcile_status AS reconcileStatus, fi.created_time AS createdTime FROM fin_invoice fi
fi.groupid = #{groupid}
fi.groupid IN
#{gid}
AND fi.invoice_date >= #{startDate}
AND fi.invoice_date <= #{endDate}
AND fi.seller_name = #{supplierName}
ORDER BY fi.invoice_date DESC

SELECT
